    "node-fetch": "^3.3.2",
    "solhint": "^5.2.0",
    "solidity-coverage": "^0.8.16",
    "ts-node": "^10.9.2",
    "typechain": "^8.3.2",
    "typescript": "^4.9.5"
  },
  "files": [
    "src",
    "deployments",
    "typechain-types",
    "!hardhat.config.*",
    "!src/test",
    "!typechain-types/test",
    "!typechain-types/factories/test",
    "!test",
    "!deploy",
    "!deployments/localhost",
    "!deployments/hardhat",
